&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de sorci&#232;re&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_sorci&#232;re_0&quot; href=&quot;#Les_arch&#233;types_de_sorci&#232;re_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amie-Des-Animaux-(Sorci&#232;re).html&quot; title=&quot;Amie des animaux&quot;&gt;Amie des animaux&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Buda-(Sorci&#232;re).html&quot; title=&quot;Buda&quot;&gt;Buda&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnoll.html&quot; title=&quot;Gnoll&quot;&gt;Gnoll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Canalisatrice-De-Mal&#233;fices-(Sorci&#232;re).html&quot; title=&quot;Canalisatrice de mal&#233;fices&quot;&gt;Canalisatrice de mal&#233;fices&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;risseuse-Balafr&#233;e-(Sorci&#232;re).html&quot; title=&quot;Gu&#233;risseuse balafr&#233;e&quot;&gt;Gu&#233;risseuse balafr&#233;e&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchetombe-(Sorci&#232;re).html&quot; title=&quot;Marchetombe&quot;&gt;Marchetombe&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Occultiste-Des-Dimensions-(Sorci&#232;re).html&quot; title=&quot;Occultiste des dimensions&quot;&gt;Occultiste des dimensions&lt;/a&gt; (RSE)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protectrice-Des-Lignes-Telluriques-(Sorci&#232;re).html&quot; title=&quot;Protectrice des lignes telluriques&quot;&gt;Protectrice des lignes telluriques&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Aux-Toxines-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re aux toxines&quot;&gt;Sorci&#232;re aux toxines&lt;/a&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-De-Lhiver-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re de l&amp;#39;hiver&quot;&gt;Sorci&#232;re de l&#39;hiver&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Des-Mers-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re des mers&quot;&gt;Sorci&#232;re des mers&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-De-Village-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re de village&quot;&gt;Sorci&#232;re de village&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Des-Montagnes-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re des montagnes&quot;&gt;Sorci&#232;re des montagnes&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Li&#233;e-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re li&#233;e&quot;&gt;Sorci&#232;re li&#233;e&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Synergiste-(Sorci&#232;re).html&quot; title=&quot;Synergiste&quot;&gt;Synergiste&lt;/a&gt; (&lt;i&gt;FF&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tisseuse-De-R&#234;ves-(Sorci&#232;re).html&quot; title=&quot;Tisseuse de r&#234;ves&quot;&gt;Tisseuse de r&#234;ves&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Changelin-(Race).html&quot; title=&quot;Les changelins&quot;&gt;Changelin&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Magic/Art de la Magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Toutes les &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;sorci&#232;res&lt;/a&gt; poss&#232;dent un lien &#233;troit avec leur familier mais l’amie des animaux s’y consacre plus particuli&#232;rement et d&#233;veloppe sa relation avec son protecteur &#224; travers son familier.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Transfert de don (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Transfert_de_don_Ext_0&quot; href=&quot;#Transfert_de_don_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; chaque fois que la sorci&#232;re apprend un don, elle peut choisir de le faire apprendre &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#FAMILIER&quot; title=&quot;La sorci&#232;re&quot;&gt;familier&lt;/a&gt;, comme don suppl&#233;mentaire. Ce dernier doit remplir les conditions requises. Si la sorci&#232;re perd son familier ou s’il meurt, elle peut r&#233;cup&#233;rer ces emplacements de don et les utiliser elle-m&#234;me ou les attribuer &#224; son nouveau familier.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Familier sup&#233;rieur (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Familier_sup&#233;rieur_Sur_1&quot; href=&quot;#Familier_sup&#233;rieur_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, l’amie des b&#234;tes renforce son lien avec son familier. Quand elle d&#233;termine les pouvoirs et les aptitudes de son familier, elle se consid&#232;re comme d’un niveau de plus qu’elle ne l’est r&#233;ellement. Ce pouvoir remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt; de sorci&#232;re de niveau 4.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Forme de familier (Mag)&lt;a class=&quot;headeranchor&quot; id=&quot;Forme_de_familier_Mag_2&quot; href=&quot;#Forme_de_familier_Mag_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 8, l’amie des b&#234;tes peut prendre la forme de son familier (ou d’une version g&#233;ante de ce familier ou d’un animal de m&#234;me type) comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Ii.html&quot; title=&quot;Forme bestiale II&quot;&gt;forme bestiale II&lt;/a&gt;&lt;/i&gt;. Par exemple, une sorci&#232;re qui poss&#232;de un rat comme familier peut se changer en rat TP, en &lt;a class=&quot;pagelink&quot; href=&quot;Rat-Sanguinaire.html&quot; title=&quot;Rat, Rat sanguinaire&quot;&gt;rat sanguinaire&lt;/a&gt; P ou en rongeur G, une sorci&#232;re qui poss&#232;de un chat comme familier peut se transformer en chat TP ou en f&#233;lin G comme un &lt;a class=&quot;pagelink&quot; href=&quot;Tigre.html&quot; title=&quot;Tigre&quot;&gt;tigre&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Lion.html&quot; title=&quot;Lion&quot;&gt;lion&lt;/a&gt;, une qui a un singe peut devenir un singe TP ou un &lt;a class=&quot;pagelink&quot; href=&quot;Gorille.html&quot; title=&quot;Singe, Gorille&quot;&gt;gorille&lt;/a&gt; G, etc. Chaque jour, la sorci&#232;re peut rester sous forme animale pendant un nombre de minutes &#233;gal &#224; son niveau. Ce pouvoir remplace le mal&#233;fice de sorci&#232;re de niveau 8.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;&#194;mes soeurs (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;&#194;mes_soeurs_Sur_3&quot; href=&quot;#&#194;mes_soeurs_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 10, si le familier ou la sorci&#232;re est gri&#232;vement bless&#233; ou sur le point de mourir, l’&#226;me &#224; l’agonie se transf&#232;re imm&#233;diatement dans le corps de l’autre. Les deux &#226;mes se partagent pacifiquement le corps survivant. Elles peuvent communiquer librement et gardent toutes deux leurs capacit&#233;s de raisonnement et leur intelligence. L’h&#244;te peut autoriser l’&#226;me invit&#233;e &#224; prendre temporairement le contr&#244;le de son corps et le r&#233;cup&#233;rer par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;. Les deux &#226;mes peuvent rester ainsi ind&#233;finiment. L’&#226;me invit&#233;e peut retourner dans son corps (s’il est disponible) en le touchant, se transf&#233;rer dans un r&#233;ceptacle adapt&#233; (comme un clone) ou prendre le contr&#244;le d’un autre corps comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Possession.html&quot; title=&quot;Possession&quot;&gt;possession&lt;/a&gt;&lt;/i&gt; (sans r&#233;ceptacle). Ce pouvoir remplace un mal&#233;fice majeur de sorci&#232;re de niveau 10.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mal&#233;fices&lt;a class=&quot;headeranchor&quot; id=&quot;Mal&#233;fices_4&quot; href=&quot;#Mal&#233;fices_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;mal&#233;fices&lt;/a&gt; de sorci&#232;re qui viennent compl&#233;ter l’arch&#233;type d’amie des b&#234;tes : &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Charme&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;charme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Langagesauvage&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;langage sauvage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Oiseaudemauvaisaugure&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;oiseau de mauvais augure&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Sceau&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;sceau&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mal&#233;fices majeurs&lt;a class=&quot;headeranchor&quot; id=&quot;Mal&#233;fices_majeurs_5&quot; href=&quot;#Mal&#233;fices_majeurs_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les mal&#233;fices majeurs de sorci&#232;re qui viennent compl&#233;ter l’arch&#233;type d’amie des b&#234;tes : &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Oeildelab&#234;te&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;oeil de la b&#234;te&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Grands mal&#233;fices&lt;a class=&quot;headeranchor&quot; id=&quot;Grands_mal&#233;fices_6&quot; href=&quot;#Grands_mal&#233;fices_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les grands mal&#233;fices de sorci&#232;re qui viennent compl&#233;ter l’arch&#233;type d’amie des b&#234;tes : &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#R&#233;incarnationforc&#233;e&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;r&#233;incarnation forc&#233;e&lt;/a&gt;.
